<!DOCTYPE html>
<html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Receipt {{ $transaction->reference_number }}</title><link href="https://fonts.googleapis.com/css2?family=Figtree:wght@400;500;600&display=swap" rel="stylesheet"><style>body{max-width:760px;margin:40px auto;padding:24px;color:#111;font:16px Figtree,Arial,sans-serif}.receipt-head{display:flex;justify-content:space-between;border-bottom:2px solid #111;padding-bottom:20px}.muted{color:#52636b}.ref{font-family:monospace}.row{display:flex;justify-content:space-between;padding:12px 0;border-bottom:1px solid #ddd}.total{font-weight:700;font-size:1.2rem}.actions{margin:24px 0}button{padding:10px 16px}@media print{.actions{display:none}body{margin:0 auto;padding:0}}</style></head><body>
<div class="actions"><button type="button" onclick="window.print()">Print receipt</button> <a href="{{ route('transactions.show', $transaction) }}">Back to transaction</a></div>
<div class="receipt-head"><div><strong>Member Desk</strong><p class="muted">Membership transaction receipt</p></div><div><span class="ref">{{ $transaction->reference_number }}</span><br>{{ $transaction->created_at->format('F j, Y') }}</div></div>
<h1>Transaction receipt</h1><p><strong>Member:</strong> {{ $transaction->member->name }} ({{ $transaction->member->membership_number }})</p><p><strong>Plan:</strong> {{ $transaction->category_name }} · {{ $transaction->level_name }} ({{ $transaction->type }})</p><p><strong>Status:</strong> {{ $transaction->status }}</p>
<h2>Payments</h2>@forelse ($transaction->payments->sortBy('paid_at') as $payment)<div class="row"><span>{{ $payment->paid_at->format('M j, Y') }} · {{ $payment->method }}<br><small class="ref">{{ $payment->reference_number }}</small></span><span>₱{{ number_format((float) $payment->amount, 2) }}</span></div>@empty<p class="muted">No payments recorded.</p>@endforelse
<div class="row"><span>Total membership fee</span><span>₱{{ number_format((float) $transaction->amount, 2) }}</span></div><div class="row total"><span>Amount paid</span><span>₱{{ number_format((float) $transaction->payments->sum('amount'), 2) }}</span></div><p class="muted">This receipt confirms recorded payments. Membership takes effect only after approval.</p>
</body></html>
